/* Lightweight Chart.js-compatible canvas renderer for the offline internship prototype. */
(function () {
  "use strict";
  function getContext(target) {
    if (!target) return null;
    if (target.getContext) return target.getContext("2d");
    if (target.canvas && target.canvas.getContext) return target.canvas.getContext("2d");
    return null;
  }
  function cssColor(index) {
    var palette = ["#2457d6", "#0f9d8a", "#f4a621", "#6b5bff", "#d64545", "#42a5f5", "#7cb342", "#ff7043"];
    return palette[index % palette.length];
  }
  function resizeCanvas(canvas) {
    var rect = canvas.getBoundingClientRect();
    var width = Math.max(320, Math.floor(rect.width || canvas.parentElement.clientWidth || 480));
    var height = Number(canvas.getAttribute("height")) || 220;
    var ratio = window.devicePixelRatio || 1;
    canvas.width = width * ratio;
    canvas.height = height * ratio;
    canvas.style.width = width + "px";
    canvas.style.height = height + "px";
    var ctx = canvas.getContext("2d");
    ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
    return { width: width, height: height, ctx: ctx };
  }
  function drawAxes(ctx, width, height, pad) {
    ctx.strokeStyle = "#d7deeb";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(pad, pad);
    ctx.lineTo(pad, height - pad);
    ctx.lineTo(width - pad / 2, height - pad);
    ctx.stroke();
  }
  function drawLabel(ctx, text, x, y, align) {
    ctx.fillStyle = "#526174";
    ctx.font = "12px Arial, sans-serif";
    ctx.textAlign = align || "center";
    ctx.fillText(String(text), x, y);
  }
  function Chart(target, config) {
    this.target = target;
    this.config = config || {};
    this.ctx = getContext(target);
    this.canvas = this.ctx ? this.ctx.canvas : null;
    this._resize = this.render.bind(this);
    if (this.canvas) {
      this.render();
      window.addEventListener("resize", this._resize);
    }
  }
  Chart.prototype.destroy = function () {
    if (this.canvas && this._resize) window.removeEventListener("resize", this._resize);
    if (this.ctx && this.canvas) this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
  };
  Chart.prototype.render = function () {
    if (!this.canvas || !this.ctx) return;
    var config = this.config || {};
    var data = config.data || {};
    var labels = data.labels || [];
    var dataset = (data.datasets && data.datasets[0]) || { data: [] };
    var values = (dataset.data || []).map(function (value) { return Number(value) || 0; });
    var box = resizeCanvas(this.canvas);
    var ctx = box.ctx;
    var width = box.width;
    var height = box.height;
    var pad = 34;
    ctx.clearRect(0, 0, width, height);
    ctx.font = "12px Arial, sans-serif";
    if (!values.length) {
      drawLabel(ctx, "No chart data available", width / 2, height / 2);
      return;
    }
    if (config.type === "doughnut") {
      var total = values.reduce(function (sum, value) { return sum + value; }, 0) || 1;
      var cx = width / 2;
      var cy = height / 2 - 6;
      var radius = Math.min(width, height) / 3.1;
      var start = -Math.PI / 2;
      values.forEach(function (value, index) {
        var angle = (value / total) * Math.PI * 2;
        ctx.beginPath();
        ctx.moveTo(cx, cy);
        ctx.arc(cx, cy, radius, start, start + angle);
        ctx.closePath();
        ctx.fillStyle = cssColor(index);
        ctx.fill();
        start += angle;
      });
      ctx.beginPath();
      ctx.arc(cx, cy, radius * 0.55, 0, Math.PI * 2);
      ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue("--surface") || "#fff";
      ctx.fill();
      drawLabel(ctx, dataset.label || "Distribution", cx, cy + 4);
      return;
    }
    var max = Math.max(100, Math.max.apply(null, values));
    drawAxes(ctx, width, height, pad);
    if (config.type === "line") {
      var step = (width - pad * 1.7) / Math.max(values.length - 1, 1);
      ctx.beginPath();
      values.forEach(function (value, index) {
        var x = pad + index * step;
        var y = height - pad - ((height - pad * 2) * value / max);
        if (index === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = cssColor(0);
      ctx.lineWidth = 3;
      ctx.stroke();
      values.forEach(function (value, index) {
        var x = pad + index * step;
        var y = height - pad - ((height - pad * 2) * value / max);
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fillStyle = cssColor(index);
        ctx.fill();
        if (index % Math.ceil(values.length / 6) === 0) drawLabel(ctx, labels[index] || "", x, height - 10);
      });
      return;
    }
    var barArea = width - pad * 1.8;
    var barWidth = Math.max(14, barArea / values.length - 8);
    values.forEach(function (value, index) {
      var x = pad + index * (barArea / values.length) + 4;
      var barHeight = (height - pad * 2) * value / max;
      var y = height - pad - barHeight;
      ctx.fillStyle = cssColor(index);
      ctx.fillRect(x, y, barWidth, barHeight);
      if (index % Math.ceil(values.length / 6) === 0) drawLabel(ctx, labels[index] || "", x + barWidth / 2, height - 10);
    });
  };
  window.Chart = window.Chart || Chart;
}());
